const M = {"features": ["loan_amount", "annual_income", "credit_score", "interest_rate", "dti_ratio", "employment_years", "late_payments", "credit_utilization"], "mean": [20369.7915, 59818.886, 682.3658, 14.5128, 0.2499, 6.1746, 0.79, 0.4013], "std": [11191.491, 28914.5253, 69.4638, 5.4787, 0.1186, 3.8473, 0.8923, 0.2117], "coef": [0.6833, -0.5909, -0.8029, 0.4401, 0.4183, -0.2897, 0.3964, 0.3135], "intercept": -0.2176};
const q = $input.first().json.query || {};
const defaults = {loan_amount:15000, annual_income:60000, credit_score:690, interest_rate:12,
                  dti_ratio:0.25, employment_years:5, late_payments:0, credit_utilization:0.35};
const labels = {loan_amount:"Loan amount ($)", annual_income:"Annual income ($)", credit_score:"Credit score (300-850)",
  interest_rate:"Interest rate (%)", dti_ratio:"Debt-to-income ratio (0-1)", employment_years:"Employment years",
  late_payments:"Late payments (count)", credit_utilization:"Credit utilization (0-1)"};
const v = {};
for (const f of M.features) { const x = parseFloat(q[f]); v[f] = Number.isFinite(x) ? x : defaults[f]; }

// logistic regression: z = b0 + sum(w_i * (x_i - mean_i)/std_i)
let z = M.intercept; const contrib = [];
M.features.forEach((f,i) => {
  const c = M.coef[i] * (v[f]-M.mean[i]) / M.std[i];
  z += c; contrib.push({feature:f, impact:+c.toFixed(3)});
});
const prob = 1/(1+Math.exp(-z));
const threshold = parseFloat(q.threshold) || 0.5;
const predicted_class = prob >= threshold ? 1 : 0;
const label = predicted_class ? "DEFAULT (High Risk)" : "NO DEFAULT (Low Risk)";
contrib.sort((a,b)=>Math.abs(b.impact)-Math.abs(a.impact));
const result = {inputs:v, default_probability:+prob.toFixed(4), threshold, predicted_class, prediction:label, top_drivers:contrib.slice(0,3)};

if (q.format === "json") return [{json:{result, html:null, isJson:true}}];

const color = predicted_class ? "#c0392b" : "#1e8449";
const fields = M.features.map(f =>
  `<label>${labels[f]}<input name="${f}" type="number" step="any" value="${v[f]}"></label>`).join("");
const drivers = result.top_drivers.map(d =>
  `<li>${labels[d.feature]}: <b style="color:${d.impact>0?'#c0392b':'#1e8449'}">${d.impact>0?'+':''}${d.impact}</b> ${d.impact>0?'(raises risk)':'(lowers risk)'}</li>`).join("");
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Loan Default Predictor</title>
<style>body{font-family:Arial,sans-serif;max-width:720px;margin:30px auto;padding:0 16px;background:#f5f6fa}
h1{font-size:22px}form{background:#fff;padding:18px;border-radius:10px;display:grid;grid-template-columns:1fr 1fr;gap:12px}
label{font-size:13px;display:flex;flex-direction:column;gap:4px}input{padding:8px;border:1px solid #ccc;border-radius:6px}
button{grid-column:1/3;padding:12px;background:#2c3e50;color:#fff;border:0;border-radius:6px;font-size:15px;cursor:pointer}
.res{margin-top:18px;background:#fff;padding:18px;border-radius:10px;border-left:8px solid ${color}}
.big{font-size:26px;font-weight:bold;color:${color}}</style></head><body>
<h1>Loan Default Prediction (n8n)</h1>
<form method="GET">${fields}<button>Predict</button></form>
<div class="res"><div class="big">${label}</div>
<p>Predicted class: <b>${predicted_class}</b> &nbsp;|&nbsp; Default probability: <b>${(prob*100).toFixed(1)}%</b> &nbsp;|&nbsp; Threshold: ${threshold}</p>
<p>Top drivers (log-odds contribution):</p><ul>${drivers}</ul></div></body></html>`;
return [{json:{result, html, isJson:false}}];
